// Generated by `npm run import:cwt` from cwtools-stellaris-config, then maintained by hand.
// Re-running the importer proposes a diff; it never overwrites hand edits automatically.

import { DefinitionTypeId } from "../catalog.js";

import {
  block,
  defineType,
  definitionLocalisation,
  field,
  fieldAbsent,
  item,
  keyedBlocks,
  occurs,
  primitive,
  typeRef,
} from "../ir.js";

import type { DefinitionType } from "../ir.js";

export const concept: DefinitionType = defineType({
  id: DefinitionTypeId.Concept,
  source: keyedBlocks("common/game_concepts"),
  // A concept with `tooltip_override = "trait:…"` shows that object's tooltip
  // instead of its own description: none of vanilla's 84 overriding concepts has
  // a `_desc`, and every one of the rest does.
  variants: [{ id: "own_tooltip", when: fieldAbsent("tooltip_override") }],
  localisation: [
    definitionLocalisation("Name", "$", true),
    definitionLocalisation("Desc", "$_desc", true, "own_tooltip"),
  ],
  modifiers: [],
  entries: [
    field("icon", primitive("file"), occurs.optional),
    field("alias", block([item(primitive("localisation"), occurs.oneOrMore)]), occurs.optional, {
      documentation: "Aliases that display the same concept Used by the base game to add singular/plural variations",
    }),
    field(
      "databank",
      block([
        field("category", typeRef("concept_categories"), occurs.one),
        field("icon", typeRef("sprite"), occurs.one),
        field("picture", typeRef("sprite"), occurs.one),
      ]),
      occurs.optional,
    ),
    field("wiki", primitive("scalar"), occurs.optional),
    field("icon", primitive("file"), occurs.optional),
    field("tooltip_override", primitive("localisation"), occurs.optional),
  ],
});
